# 3.4 — lọc (≈ Filter Current Log), tìm chữ (≈ Find), lọc theo người dùng, xuất CSV; cùng bộ lọc viết bằng jq cho người dùng Linux/macOS.
@ps $r = evtx-rec mau/dbc-many-events-system.evtx | ConvertFrom-Json; $cuoi = ($r.t | Measure-Object -Maximum).Maximum; "Su kien cuoi: $($cuoi.ToString('yyyy-MM-dd HH:mm:ss')) UTC"; $r | Where-Object { $_.muc -in 'Critical','Error','Warning' -and $_.t -ge $cuoi.AddDays(-7) } | Group-Object muc,nguon,id | Sort-Object Count -Descending | Select-Object Count,Name | Format-Table -AutoSize
@ps evtx-rec mau/dbc-many-events-system.evtx | ConvertFrom-Json | Where-Object id -in 1074,6005,6006,6008,41 | Group-Object id | Select-Object Count,Name | Format-Table -AutoSize
@ps evtx-rec mau/dbc-many-events-system.evtx | ConvertFrom-Json | Where-Object sid | Group-Object sid | Sort-Object Count -Descending | Select-Object -First 5 Count,Name | Format-Table -AutoSize
@ps evtx-rec mau/dbc-many-events-system.evtx | ConvertFrom-Json | Where-Object { ($_.data.PSObject.Properties.Value -join ' ') -match 'KB2' } | Select-Object -First 4 @{n='Luc';e={$_.t.ToString('yyyy-MM-dd HH:mm')}},nguon,id,@{n='Data';e={(($_.data.PSObject.Properties.Value -join ' | ') -replace '\s+',' ').Substring(0,70)}} | Format-Table -AutoSize
@ps evtx-rec mau/dbc-many-events-system.evtx | ConvertFrom-Json | Where-Object id -eq 1074 | Select-Object -First 20 @{n='Luc';e={$_.t.ToString('s')}},may,@{n='TienTrinh';e={$_.data.'#text'[0]}},@{n='LyDo';e={$_.data.'#text'[2]}},@{n='Kieu';e={$_.data.'#text'[4]}},@{n='NguoiDung';e={$_.data.'#text'[6]}} | Export-Csv -NoTypeInformation -Encoding utf8 ra/1074.csv; Get-Content ra/1074.csv -TotalCount 4; (Import-Csv ra/1074.csv).Count
evtx-rec mau/dbc-many-events-system.evtx | jq -r 'select(.muc=="Error") | "\(.nguon) \(.id)"' | sort | uniq -c | sort -rn | head -5
